+package com.example;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @BeforeEach void open() { navigate(ContactView.class); }
+    TextField name() { return $(TextField.class).withLabel("Name").single(); }
+    TextField phone() { return $(TextField.class).withLabel("Phone").single(); }
+    EmailField email() { return $(EmailField.class).single(); }
+    TextArea message() { return $(TextArea.class).single(); }
+    Button send() { return $(Button.class).withText("Send").single(); }
+    void click(String text) { test($(Button.class).withText(text).single()).click(); }
+    int rows() { return test($(Grid.class).single()).size(); }
+
+    @Test void validatesAllFieldsWithoutSendingOrClearing() {
+        assertTrue(send().isEnabled());
+        click("Send");
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        test(name()).setValue("  ");
+        test(email()).setValue("bad-address");
+        test(phone()).setValue("123");
+        test(message()).setValue("x".repeat(501));
+        click("Send");
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals(501, message().getValue().length());
+        assertEquals(0, rows());
+        assertFalse($(Notification.class).exists());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test void sendsByClickAndEnterAndRetainsNewestFirstAcrossNavigation() {
+        test(name()).setValue("First");
+        test(phone()).setValue("123");
+        test(message()).setValue("x".repeat(500));
+        click("Send");
+        assertEquals(1, rows());
+        assertTrue($(Notification.class).exists());
+        assertTrue(name().isEmpty() && phone().isEmpty() && email().isEmpty() && message().isEmpty());
+        assertFalse(send().isEnabled());
+        test(email()).setValue("second@example.com");
+        assertTrue(send().isEnabled());
+        test(name()).setValue("Second");
+        test(message()).setValue("Hello");
+        fireShortcut(Key.ENTER);
+        assertEquals(2, rows());
+        assertFalse(send().isEnabled());
+        test($(RouterLink.class).single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+        assertFalse($(Dialog.class).exists());
+        navigate(ContactView.class);
+        assertTrue(send().isEnabled());
+        assertEquals(2, rows());
+        assertEquals("Second", test($(Grid.class).single()).getCellText(0, 0));
+    }
+
+    @Test void routerLinkAndProgrammaticNavigationProtectDraft() {
+        test(message()).setValue("Draft");
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened());
+        click("Keep editing");
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("Draft", message().getValue());
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue($(Dialog.class).single().isOpened());
+        click("Discard");
+        assertEquals("About", $(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertTrue(message().isEmpty());
+        assertEquals(0, rows());
+    }
+
+    @Test void everyFieldEditReenablesSendAndClearedDraftDoesNotBlockNavigation() {
+        for (String field : new String[]{"Name", "Email", "Phone", "Message"}) {
+            name().setValue("Sender");
+            phone().setValue("123");
+            email().clear();
+            message().setValue("Hello");
+            click("Send");
+            assertFalse(send().isEnabled());
+            switch (field) {
+                case "Name" -> test(name()).setValue("N");
+                case "Email" -> test(email()).setValue("e@example.com");
+                case "Phone" -> test(phone()).setValue("1");
+                case "Message" -> test(message()).setValue("M");
+            }
+            assertTrue(send().isEnabled());
+            UI.getCurrent().navigate(AboutView.class);
+            assertTrue($(Dialog.class).single().isOpened());
+            click("Keep editing");
+            name().clear(); email().clear(); phone().clear(); message().clear();
+            assertTrue(send().isEnabled());
+            UI.getCurrent().navigate(AboutView.class);
+            assertEquals("About", $(H1.class).single().getText());
+            navigate(ContactView.class);
+        }
+    }
+}
